from public.decks d
join (values
  ('Dear', '/dɪə/', 'Kính gửi, Thân gửi (mở đầu thư)', 'Dear Ms. Tran, thank you for your email.', 'Kính gửi bà Trần, cảm ơn email của bà.', 1),
