-- Họp & thuyết trình (100 từ)
insert into public.decks (slug, name, description, level, category, position)
values ('cong-viec-hop', 'Họp & thuyết trình', 'Điều hành cuộc họp, trình bày, phản hồi', 'intermediate', 'cong-viec', 20)
on conflict (slug) do update set
  name = excluded.name, description = excluded.description, level = excluded.level,
  category = excluded.category, position = excluded.position;

insert into public.words (deck_id, term, phonetic, meaning_vi, example_en, example_vi, position)
select d.id, w.term, w.phonetic, w.meaning_vi, w.example_en, w.example_vi, w.position
from public.decks d
join (values
  ('agenda', '/əˈdʒendə/', 'chương trình họp (n)', 'I''ve sent the agenda for tomorrow''s meeting.', 'Tôi đã gửi chương trình cho cuộc họp ngày mai.', 1),
  ('minutes', '/ˈmɪnɪts/', 'biên bản họp (n)', 'Who is taking the minutes today?', 'Hôm nay ai ghi biên bản?', 2),
  ('chair', '/tʃeə/', 'chủ trì (v); người chủ trì (n)', 'Linh will chair the meeting.', 'Linh sẽ chủ trì cuộc họp.', 3),
  ('attendee', '/əˌtenˈdiː/', 'người tham dự (n)', 'There were twelve attendees.', 'Có mười hai người tham dự.', 4),
